from scapy.all import sniff, TCP, IP
pkts = sniff(offline='capture.pcap', filter='tcp port 443', count=10)
sessions = {}
for pkt in pkts:
    if IP in pkt and TCP in pkt:
        key = (pkt[IP].src, pkt[IP].dst, pkt[TCP].sport, pkt[TCP].dport)
        sessions[key] = sessions.get(key, 0) + 1
print(len(sessions))

from scapy.all import rdpcap, TCP
pkts = rdpcap('http_traffic.pcap')
http_methods = []
for pkt in pkts:
    if TCP in pkt and pkt[TCP].dport == 80:
        payload = bytes(pkt[TCP].payload)
        if payload.startswith(b'GET'):
            http_methods.append('GET')
        elif payload.startswith(b'POST'):
            http_methods.append('POST')
print(len(http_methods))

import asyncio
class EchoProtocol(asyncio.Protocol):
    def connection_made(self, transport):
        self.transport = transport
    def data_received(self, data):
        self.transport.write(data.upper())
async def main():
    loop = asyncio.get_running_loop()
    server = await loop.create_server(EchoProtocol, '127.0.0.1', 8888)
    return type(server)
print(asyncio.run(main()))

